// What ASARI exports now vs what Elliot has: fetch only new and changed
// listings (at most MAX per run; the rest next time, oldest first is fine).
// ASARI allows 25 calls a minute, so Get Listing waits 2.6 s between calls.
const MAX = 150;
const agency = $('Pick Agency').first().json;
let known = agency.known || {};
if (typeof known === 'string') { try { known = JSON.parse(known); } catch (e) { known = {}; } }
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const base = { tenant_id: agency.tenant_id };
if (!(status >= 200 && status < 300) || !body || body.success === false || !Array.isArray(body.data)) {
  const why = (body && (body.error || (body.parameterErrors && JSON.stringify(body.parameterErrors))))
    || (status === 401 || status === 403 ? 'ASARI refused the user ID or token' : `ASARI answered HTTP ${status || 'nothing'}`);
  return [{ json: { ...base, ok: false, error: String(why).slice(0, 300), exported_ids: null, to_fetch: [], total: 0 } }];
}
const entries = body.data.map((x) => (typeof x === 'object' && x !== null
  ? { id: String(x.id ?? x.listingId ?? ''), version: String(x.lastUpdated ?? x.updated ?? x.modificationDate ?? '') }
  : { id: String(x), version: '' })).filter((x) => x.id);
const toFetch = entries.filter((e) => !(e.id in known) || (e.version && known[e.id] !== e.version)).map((e) => e.id);
return [{ json: { ...base, ok: true, error: null, exported_ids: entries.map((e) => e.id), to_fetch: toFetch.slice(0, MAX),
  left_for_next_run: Math.max(0, toFetch.length - MAX), total: entries.length } }];

// ASARI listing (apiSite /site/listing) → an Elliot listing (0044). ASARI's
// field names vary between accounts and versions, so each value is looked for
// under the names it is known to use; the whole original is kept in `raw`, so
// the mapping can be improved later without asking ASARI again.
const IMG = 'https://img.asariweb.pl/normal/';
const pick = (o, ...paths) => {
  for (const p of paths) {
    const v = p.split('.').reduce((x, k) => (x == null ? undefined : x[k]), o);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return null;
};
const num = (v) => {
  if (v == null || v === '') return null;
  if (typeof v === 'object') v = v.amount ?? v.value;
  const n = Number(String(v).replace(/\s/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const int = (v) => {
  if (v == null || v === '') return null;
  if (/^(parter|ground|0)$/i.test(String(v).trim())) return 0;
  const n = parseInt(String(v), 10);
  return Number.isFinite(n) ? n : null;
};
const text = (v) => (v == null ? null : typeof v === 'object' ? (v.name ?? v.value ?? null) : String(v).trim() || null);
const strip = (h) => (h == null ? null : String(h).replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n\n').replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/\n{3,}/g, '\n\n').trim() || null);

function mapAsari(l) {
  const section = String(pick(l, 'section', 'sectionName', 'type') || '');
  const transaction_type = /rent|lease|wynaj|najem/i.test(section) ? 'rent' : 'sale';
  // Commercial first: "WarehouseSale" contains "house".
  const property_type = /commercial|office|warehouse|premises|object|lokal|biur|magazyn|hala/i.test(section) ? 'commercial'
    : /apartment|flat|mieszk/i.test(section) ? 'apartment'
    : /house|dom/i.test(section) ? 'house'
    : /lot|plot|dzia|grunt/i.test(section) ? 'plot'
    : /room|pok[oó]j/i.test(section) ? 'room'
    : 'other';
  const statusRaw = String(pick(l, 'status', 'listingStatus') || '');
  const status = /sold|sprzedan/i.test(statusRaw) ? 'sold'
    : /rented|wynaj[eę]t/i.test(statusRaw) ? 'let'
    : /reserv|rezerw/i.test(statusRaw) ? 'under_offer'
    : /withdraw|archiv|inactive|closed|wycofan/i.test(statusRaw) ? 'withdrawn'
    : 'available';
  const price = num(pick(l, 'price', 'totalPrice', 'priceAmount'));
  const currency = String(pick(l, 'price.currency', 'currency') || 'PLN').toUpperCase().replace('ZŁ', 'PLN');
  const area = num(pick(l, 'totalArea', 'usableArea', 'area', 'lotArea'));
  const rooms = int(pick(l, 'noOfRooms', 'roomsNo', 'rooms', 'numberOfRooms'));
  const city = text(pick(l, 'location.locality', 'location.city', 'city', 'locality'));
  const district = text(pick(l, 'location.quarter', 'location.district', 'quarter', 'district', 'location.subLocality'));
  const street = text(pick(l, 'street', 'location.street', 'streetName'));
  const streetNo = text(pick(l, 'streetNumber', 'location.streetNumber', 'houseNumber'));
  const address = street ? [street, streetNo].filter(Boolean).join(' ') : null;
  const reference = text(pick(l, 'listingId', 'signature', 'number', 'offerNumber'));
  const typeWord = { apartment: 'Mieszkanie', house: 'Dom', plot: 'Działka', room: 'Pokój', commercial: 'Lokal', other: 'Nieruchomość' }[property_type];
  const fallbackTitle = [typeWord + (transaction_type === 'rent' ? ' na wynajem' : ''), rooms ? `${rooms} pok.` : null, area ? `${area} m²` : null, district || city]
    .filter(Boolean).join(', ');
  const title = text(pick(l, 'name', 'title', 'headerAdvertisement', 'advertisementTitle')) || fallbackTitle;
  const images = pick(l, 'images', 'photos', 'imageList') || [];
  const photos = (Array.isArray(images) ? images : [])
    .map((i) => (typeof i === 'object' ? (i.url || (i.id != null ? IMG + i.id : null)) : (/^https?:/.test(String(i)) ? String(i) : IMG + i)))
    .filter(Boolean).slice(0, 30);
  const features = [
    pick(l, 'balcony') ? 'balcony' : null, pick(l, 'terrace') ? 'terrace' : null, pick(l, 'garden') ? 'garden' : null,
    pick(l, 'elevator', 'lift') ? 'lift' : null, pick(l, 'parkingSpace', 'garage', 'parking') ? 'parking' : null,
    pick(l, 'basement', 'cellar') ? 'cellar' : null,
  ].filter(Boolean);
  const avail = text(pick(l, 'availableFrom', 'availability'));
  return {
    external_id: String(pick(l, 'id') ?? ''),
    external_version: String(pick(l, 'lastUpdated', 'updated', 'modificationDate') ?? ''),
    reference,
    title: String(title).slice(0, 300),
    status,
    transaction_type,
    property_type,
    price,
    currency: /^[A-Z]{3}$/.test(currency) ? currency : 'PLN',
    city, district, address,
    area_m2: area,
    rooms,
    bedrooms: int(pick(l, 'noOfBedrooms', 'bedrooms')),
    bathrooms: int(pick(l, 'noOfBathrooms', 'bathrooms')),
    floor: int(pick(l, 'floorNo', 'floor')),
    description: strip(pick(l, 'description', 'descriptionPl')),
    features,
    photos,
    image_url: photos[0] || null,
    available_from: avail && /^\d{4}-\d{2}-\d{2}/.test(avail) ? avail.slice(0, 10) : null,
    raw: l,
  };
}


// One item per Get Listing answer; ASARI's { success, data } wrapper.
const rows = [];
let failed = 0;
for (const it of $input.all()) {
  const r = it.json;
  let body = r.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const st = Number(r.statusCode || 0);
  const l = body && body.success !== false ? (body.data || null) : null;
  if (!(st >= 200 && st < 300) || !l || typeof l !== 'object') { failed += 1; continue; }
  const m = mapAsari(l);
  if (m.external_id) rows.push(m); else failed += 1;
}
return [{ json: { tenant_id: $('Plan Sync').first().json.tenant_id, rows, failed } }];

