={{ (() => {
  const plan = $('Plan Sync').first().json;
  const safe = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
  const mapped = safe('Map Listings') || {};
  let saved = (safe('Save Listings') || {}).result || {};
  if (typeof saved === 'string') { try { saved = JSON.parse(saved); } catch (e) { saved = {}; } }
  const counts = { exported: plan.total || 0, fetched: (plan.to_fetch || []).length, new: saved.new || 0, updated: saved.updated || 0,
    failed: (mapped.failed || 0) + (saved.skipped || 0), left_for_next_run: plan.left_for_next_run || 0 };
  return [ plan.tenant_id, plan.exported_ids ? JSON.stringify(plan.exported_ids) : null, plan.error || '', JSON.stringify(counts) ];
})() }}
